CREATE TRIGGER RefCusTaxOrFeeLanguage_Combined
	ON RefCusTaxOrFeeLanguage
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZXU_DataSetPK = ZX0_PK,
		ZXU_DataSetCode = 'ZX0'
		FROM RefCusTaxOrFeeLanguage t
		JOIN inserted ON t.ZXU_PK = inserted.ZXU_PK
		LEFT JOIN RefCusTaxOrFee ON inserted.ZXU_ZZF_TaxOrFee = ZZF_PK
		LEFT JOIN RefCusTaxOrFeeType ON ZZF_ZX0_NKTaxOrFeeType = ZX0_TaxOrFeeType
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZXU_DataSetPK, t.ZXU_DataSetCode
	FROM RefCusTaxOrFeeLanguage t
	JOIN inserted ON t.ZXU_PK = inserted.ZXU_PK
	UNION
	SELECT ZXU_DataSetPK, ZXU_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

